// Native validation used by our account helper. Generated bytes remain in memory.
#import <Foundation/Foundation.h>
#import <objc/runtime.h>
#import <objc/message.h>
#include <dlfcn.h>
#include <unistd.h>

static BOOL appleURL(NSURL *url) {
    NSString *host = url.host.lowercaseString;
    return [url.scheme.lowercaseString isEqual:@"https"] && !url.user && !url.password
        && (!url.port || url.port.intValue == 443)
        && ([host isEqual:@"apple.com"] || [host hasSuffix:@".apple.com"]);
}

@interface MPAppleRedirectPolicy : NSObject <NSURLSessionTaskDelegate>
@end
@implementation MPAppleRedirectPolicy
- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task
 willPerformHTTPRedirection:(NSHTTPURLResponse *)response newRequest:(NSURLRequest *)request
 completionHandler:(void (^)(NSURLRequest *))completionHandler {
    completionHandler(appleURL(request.URL) ? request : nil);
}
@end

char *mp_device_validation(const unsigned char *certBytes, size_t certLength, const char *initializeURL) {
    @autoreleasepool {
        char *encoded = NULL;
        NSMutableDictionary *report = [@{@"probe":@"own-process local device-validation handshake",
            @"account_lookup_called":@NO, @"account_login_called":@NO,
            @"ids_registration_called":@NO, @"messages_read":@NO, @"send_called":@NO,
            @"messages_app_attached":@NO, @"validation_bytes_saved":@NO,
            @"validation_bytes_printed":@NO, @"handshake_success":@NO} mutableCopy];
        do {
            NSURL *url = [NSURL URLWithString:@(initializeURL)];
            if (!appleURL(url)) { report[@"failure_stage"] = @"endpoint_policy"; break; }
            NSData *cert = [NSData dataWithBytes:certBytes length:certLength];
            if (!cert.length || cert.length > 65536) { report[@"failure_stage"] = @"certificate"; break; }
            void *framework = dlopen("/System/Library/PrivateFrameworks/AppleAccount.framework/AppleAccount", RTLD_NOW | RTLD_LOCAL);
            Class cls = framework ? NSClassFromString(@"AAAbsintheContext") : Nil;
            if (!cls) { report[@"failure_stage"] = @"class"; break; }
            unsigned int count = 0;
            Method *list = class_copyMethodList(cls, &count);
            NSMutableArray<NSString *> *objects = [NSMutableArray array];
            NSMutableArray<NSString *> *bools = [NSMutableArray array];
            for (unsigned int i = 0; i < count; ++i) {
                NSString *name = NSStringFromSelector(method_getName(list[i]));
                if (![name hasSuffix:@":error:"]) continue;
                const char *type = method_getTypeEncoding(list[i]);
                if (!strcmp(type,"@32@0:8@16^@24")) [objects addObject:name];
                if (!strcmp(type,"B32@0:8@16^@24")) [bools addObject:name];
            }
            free(list);
            if (objects.count != 2 || bools.count != 1) { report[@"failure_stage"] = @"selector_abi"; break; }
            id context = nil;
            NSData *requestBytes = nil;
            NSString *signName = nil;
            NSUInteger successes = 0;
            for (NSString *name in objects) {
                id trial = [[cls alloc] init];
                NSError *error = nil;
                id result = ((id (*)(id,SEL,id,NSError **))objc_msgSend)(trial,NSSelectorFromString(name),cert,&error);
                if ([result isKindOfClass:NSData.class] && [result length] > 0 && !error) {
                    successes++; context = trial; requestBytes = result;
                    signName = [objects[0] isEqual:name] ? objects[1] : objects[0];
                }
            }
            report[@"initializer_candidates_succeeded"] = @(successes);
            if (successes != 1 || requestBytes.length > 65536) { report[@"failure_stage"] = @"native_initialize"; break; }
            report[@"native_initialize_success"] = @YES;
            NSError *error = nil;
            NSData *body = [NSPropertyListSerialization dataWithPropertyList:@{@"session-info-request":requestBytes}
                format:NSPropertyListXMLFormat_v1_0 options:0 error:&error];
            if (!body) { report[@"failure_stage"] = @"request_encoding"; break; }
            NSURLSessionConfiguration *configuration = NSURLSessionConfiguration.ephemeralSessionConfiguration;
            configuration.HTTPCookieStorage = nil;
            configuration.HTTPShouldSetCookies = NO;
            configuration.URLCredentialStorage = nil;
            configuration.timeoutIntervalForRequest = 15;
            configuration.timeoutIntervalForResource = 20;
            MPAppleRedirectPolicy *policy = [MPAppleRedirectPolicy new];
            NSURLSession *session = [NSURLSession sessionWithConfiguration:configuration delegate:policy delegateQueue:nil];
            NSMutableURLRequest *request = [NSMutableURLRequest requestWithURL:url];
            request.HTTPMethod = @"POST"; request.HTTPBody = body;
            [request setValue:@"application/x-apple-plist" forHTTPHeaderField:@"Content-Type"];
            dispatch_semaphore_t semaphore = dispatch_semaphore_create(0);
            __block NSData *response = nil;
            __block NSInteger httpStatus = 0;
            __block NSInteger networkError = 0;
            NSURLSessionDataTask *task = [session dataTaskWithRequest:request completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
                response = data; networkError = err.code;
                if ([resp isKindOfClass:NSHTTPURLResponse.class]) httpStatus = [(NSHTTPURLResponse *)resp statusCode];
                dispatch_semaphore_signal(semaphore);
            }];
            [task resume];
            long timeout = dispatch_semaphore_wait(semaphore,dispatch_time(DISPATCH_TIME_NOW,22*NSEC_PER_SEC));
            [session invalidateAndCancel];
            report[@"apple_handshake_http_status"] = @(httpStatus);
            report[@"network_error_code"] = @(networkError);
            if (timeout || networkError || httpStatus != 200 || !response || response.length > 1048576) {
                report[@"failure_stage"] = @"apple_handshake"; break;
            }
            id plist = [NSPropertyListSerialization propertyListWithData:response options:0 format:nil error:&error];
            NSData *info = [plist isKindOfClass:NSDictionary.class] ? plist[@"session-info"] : nil;
            if (![info isKindOfClass:NSData.class] || !info.length || info.length > 65536) {
                report[@"failure_stage"] = @"response_schema"; break;
            }
            error = nil;
            BOOL keyOK = ((BOOL (*)(id,SEL,id,NSError **))objc_msgSend)(context,NSSelectorFromString(bools[0]),info,&error);
            report[@"native_key_establishment_success"] = @(keyOK && !error);
            if (!keyOK || error) { report[@"failure_stage"] = @"native_key_establishment"; break; }
            id validation = ((id (*)(id,SEL,id,NSError **))objc_msgSend)(context,NSSelectorFromString(signName),nil,&error);
            if (![validation isKindOfClass:NSData.class] || ![validation length] || error) {
                report[@"failure_stage"] = @"native_sign"; break;
            }
            report[@"validation_byte_count"] = @([validation length]);
            report[@"handshake_success"] = @YES;
            encoded = strdup([(NSData *)validation base64EncodedStringWithOptions:0].UTF8String);
        } while (0);
        return encoded;
    }
}
